import { pool } from './db';
import { notifyNewPost } from './telegram';

// AI personas: a dozen recurring "regulars" that reply to REAL users' forum posts
// so threads feel alive. Each has a fixed character and a set of categories they
// care about — a car/money guy never shows up in a parenting thread. Replies are
// generated by DeepSeek (same provider as moderation) and inserted after a human-
// like delay. They only ever answer humans, never each other (no bot loops).

const API_KEY = process.env.DEEPSEEK_API_KEY || '';
const API_URL = process.env.DEEPSEEK_API_URL || 'https://api.deepseek.com/chat/completions';
const MODEL = process.env.DEEPSEEK_MODEL || 'deepseek-chat';
export const personasEnabled = () => !!API_KEY;

// Reply delay window (feels like a person noticing and typing). Override via env.
const MIN_DELAY = Number(process.env.PERSONA_MIN_DELAY_MS || 25_000);
const MAX_DELAY = Number(process.env.PERSONA_MAX_DELAY_MS || 150_000);
// Chance a human post gets any persona reply at all (not every post does).
const REPLY_CHANCE = Number(process.env.PERSONA_REPLY_CHANCE || 0.9);
// How many personas chime in: always ≥1, then a 2nd/3rd with these chances.
const SECOND_CHANCE = Number(process.env.PERSONA_SECOND_CHANCE || 0.5);
const THIRD_CHANCE = Number(process.env.PERSONA_THIRD_CHANCE || 0.25);
// Chance a given reply targets the human who just posted (vs another participant).
const HUMAN_TARGET_CHANCE = Number(process.env.PERSONA_HUMAN_TARGET_CHANCE || 0.6);

interface Persona {
  username: string; // reuse existing seed handles so they already have history
  display: string;
  bio: string;
  interests: string[]; // category slugs this persona engages in
  character: string; // steering prompt: who they are + how they write
}

